<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3'; import { reactive } from 'vue'; import ErpLayout from '@/Layouts/ErpLayout.vue'; import type { BranchOption, PaginationMeta, StatusOption, TreasuryAdjustmentSummary } from '@/Types/treasury'; defineOptions({ layout: ErpLayout });
const props=defineProps<{documents:{data:TreasuryAdjustmentSummary[];meta:PaginationMeta};filters:{search:string;status:string;adjustment_type:string;branch_id:number|null;per_page:number};statuses:StatusOption[];types:StatusOption[];branches:BranchOption[];can:{create:boolean}}>(); const filters=reactive({...props.filters}); const apply=(page=1):void=>router.get(route('treasury-adjustments.index'),{...filters,page},{preserveState:true,replace:true}); const money=(v:string):string=>new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:6}).format(Number(v)); const remove=(id:number):void=>{if(window.confirm('Delete this Treasury Adjustment draft?'))router.delete(route('treasury-adjustments.destroy',id));};
</script>
<template><Head title="Treasury Adjustments"/><div class="space-y-6"><div class="flex justify-between"><div><h1 class="text-2xl font-semibold">Treasury Adjustments</h1><p class="mt-1 text-sm text-gray-500">Bank charges, interest, and statement adjustments.</p></div><Link v-if="can.create" :href="route('treasury-adjustments.create')" class="h-fit rounded-lg bg-brand-500 px-4 py-2.5 text-sm text-white">New Adjustment</Link></div><div class="rounded-2xl border bg-white p-5 dark:border-gray-800 dark:bg-gray-900"><div class="grid gap-4 md:grid-cols-5"><input v-model="filters.search" placeholder="Number, reference, description" class="h-11 rounded-lg border px-3 dark:border-gray-700"/><select v-model="filters.adjustment_type" class="h-11 rounded-lg border px-3 dark:border-gray-700"><option value="">All types</option><option v-for="t in types" :key="t.value" :value="t.value">{{t.label}}</option></select><select v-model="filters.status" class="h-11 rounded-lg border px-3 dark:border-gray-700"><option value="">All statuses</option><option v-for="s in statuses" :key="s.value" :value="s.value">{{s.label}}</option></select><select v-model="filters.branch_id" class="h-11 rounded-lg border px-3 dark:border-gray-700"><option :value="null">All branches</option><option v-for="b in branches" :key="b.id" :value="b.id">{{b.name}}</option></select><button class="rounded-lg bg-brand-500 text-sm text-white" @click="apply()">Apply</button></div></div><div class="overflow-hidden rounded-2xl border bg-white dark:border-gray-800 dark:bg-gray-900"><div class="overflow-x-auto"><table class="min-w-[1000px] w-full"><thead class="bg-gray-50 dark:bg-white/[.03]"><tr><th class="p-4 text-left text-xs uppercase text-gray-500">Adjustment</th><th class="p-4 text-left text-xs uppercase text-gray-500">Bank Account</th><th class="p-4 text-left text-xs uppercase text-gray-500">Offset</th><th class="p-4 text-left text-xs uppercase text-gray-500">Date</th><th class="p-4 text-right text-xs uppercase text-gray-500">Amount</th><th class="p-4 text-left text-xs uppercase text-gray-500">Status</th><th class="p-4 text-right text-xs uppercase text-gray-500">Actions</th></tr></thead><tbody class="divide-y dark:divide-gray-800"><tr v-for="d in documents.data" :key="d.id"><td class="p-4"><Link :href="route('treasury-adjustments.show',d.id)" class="font-medium text-brand-600">{{d.adjustment_number??`Draft #${d.id}`}}</Link><p class="text-xs text-gray-500">{{d.adjustment_type_label}}</p></td><td class="p-4 text-sm">{{d.bank_account?.code}} — {{d.bank_account?.name}}<p class="text-xs text-gray-500">{{d.branch?.name}}</p></td><td class="p-4 text-sm">{{d.offset_account?.code}} — {{d.offset_account?.name}}</td><td class="p-4 text-sm">{{d.adjustment_date}}</td><td class="p-4 text-right font-semibold">{{d.currency_code}} {{money(d.amount)}}</td><td class="p-4"><span class="rounded-full bg-gray-100 px-2.5 py-1 text-xs dark:bg-gray-800">{{d.status_label}}</span></td><td class="p-4 text-right"><Link v-if="d.can.update" :href="route('treasury-adjustments.edit',d.id)" class="mr-3 text-sm">Edit</Link><button v-if="d.can.delete" class="text-sm text-error-600" @click="remove(d.id)">Delete</button></td></tr><tr v-if="documents.data.length===0"><td colspan="7" class="p-12 text-center text-sm text-gray-500">No adjustments found.</td></tr></tbody></table></div><div class="flex justify-between border-t p-4 text-sm dark:border-gray-800"><span>{{documents.meta.total}} records</span><div class="flex gap-2"><button :disabled="documents.meta.current_page<=1" class="rounded border px-3 py-1 disabled:opacity-50" @click="apply(documents.meta.current_page-1)">Previous</button><button :disabled="documents.meta.current_page>=documents.meta.last_page" class="rounded border px-3 py-1 disabled:opacity-50" @click="apply(documents.meta.current_page+1)">Next</button></div></div></div></div></template>
